export function bounds(a: Shape, b: Shape) {
  const ra = { x: a.x - a.stroke / 2, y: a.y - a.stroke / 2, w: a.w + a.stroke, h: a.h + a.stroke };
  const rb = { x: b.x - b.stroke / 2, y: b.y - b.stroke / 2, w: b.w + b.stroke, h: b.h + b.stroke };
  return union(ra, rb);
}

new:
function outer(s: Shape) {
  return { x: s.x - s.stroke / 2, y: s.y - s.stroke / 2, w: s.w + s.stroke, h: s.h + s.stroke };
}

export function bounds(a: Shape, b: Shape) {
  return union(outer(a), outer(b));
}
